settings.custom_css:
/* Eat&Go Side Cart Container Custom Overrides */
.elementor-menu-cart__container { width: 420px !important; max-width: 100vw !important; }
.elementor-menu-cart__main { background-color: #FFFFFF !important; box-shadow: -8px 0 32px rgba(0,0,0,0.2) !important; }
.elementor-menu-cart__header { background-color: #18181B !important; color: #FFFFFF !important; padding: 18px 20px !important; }
.elementor-menu-cart__header .elementor-menu-cart__header-title { font-family: 'Open Sans', sans-serif !important; font-weight: 700 !important; color: #FFFFFF !important; font-size: 16px !important; }
.elementor-menu-cart__close-button { color: #FFFFFF !important; }
.elementor-menu-cart__product-image img { border-radius: 12px !important; object-fit: cover !important; }
.elementor-menu-cart__product-name, .elementor-menu-cart__product-name a { color: #18181B !important; font-family: 'Open Sans', sans-serif !important; font-weight: 700 !important; }
.elementor-menu-cart__product-price { color: #FF5500 !important; font-weight: 700 !important; }
.elementor-menu-cart__bottom { background-color: #F4F4F5 !important; padding: 16px 20px !important; border-top: 1px solid #E4E4E7 !important; }
.elementor-menu-cart__subtotal { font-family: 'Open Sans', sans-serif !important; font-size: 18px !important; font-weight: 700 !important; color: #18181B !important; }
.elementor-menu-cart__checkout-button, a.elementor-button--checkout { background-color: #00C853 !important; color: #FFFFFF !important; border-radius: 50px !important; font-family: 'Open Sans', sans-serif !important; font-weight: 800 !important; font-size: 14px !important; padding: 14px 20px !important; width: 100% !important; text-align: center !important; text-transform: none !important; box-shadow: 0 4px 14px rgba(0,200,83,0.3) !important; }
.elementor-menu-cart__checkout-button:hover, a.elementor-button--checkout:hover { background-color: #059669 !important; color: #FFFFFF !important; }
